window.JOHTO_LEAGUE = [{"trainer":"HGSS_TRAINER_ELITE_FOUR_WILL_WILL","rematch":"HGSS_TRAINER_ELITE_FOUR_WILL_WILL_2","intro":["Welcome to the Pokémon League!","Allow me to introduce myself.\nI am Will.","I have trained all around the world,","making my Psychic-type Pokémon\npowerful.","And, at last, I've been accepted into\nthe Elite Four.","I can only keep getting better!","Losing is not an option!"],"after":["Even though I was defeated, I won't\nchange my course.","I will continue battling until I stand\nabove all Trainers!","Now move on and experience\nthe true ferocity of the Elite Four."],"look":{"sprite":"hgss_gsbigfour1","width":32,"height":32,"frames":9,"offsetX":-8}},{"trainer":"HGSS_TRAINER_ELITE_FOUR_KOGA_KOGA","rematch":"HGSS_TRAINER_ELITE_FOUR_KOGA_KOGA_2","intro":["Fwahahahaha!","I am Koga of the Elite Four.\nI live in shadows--a ninja!","My intricate style will confound and\ndestroy you!","Confusion, sleep, poison...","Prepare to be the victim of my\nsinister techniques!","Fwahahahaha!","Pokémon are not merely about brute\nforce--you shall see soon enough!"],"after":["I subjected you to everything I could\nmuster. But my efforts failed.","I must hone my skills.","Go on to the next room, and\nput your abilities to the test!"],"look":{"sprite":"hgss_gsbigfour2","width":32,"height":32,"frames":9,"offsetX":-8}},{"trainer":"HGSS_TRAINER_ELITE_FOUR_BRUNO_BRUNO","rematch":"HGSS_TRAINER_ELITE_FOUR_BRUNO_BRUNO_2","intro":["I am Bruno of the Elite Four.","I always train to the extreme because\nI believe in our potential.","That is how we became strong.\nCan you withstand our power?","Hm? I see no fear in you. You look\ndetermined. Perfect for battle!","Ready, {PLAYER}?","You will bow down to our\noverwhelming power!","Hoo hah!"],"after":["Having lost, I have no right to\nsay anything...","Go face your next challenge!"],"look":{"sprite":"hgss_gsbigfour3","width":32,"height":32,"frames":9,"offsetX":-8}},{"trainer":"HGSS_TRAINER_ELITE_FOUR_KAREN_KAREN","rematch":"HGSS_TRAINER_ELITE_FOUR_KAREN_KAREN_2","intro":["I am Karen of the Elite Four.","You're {PLAYER}? How amusing.\nI love Dark-type Pokémon.","I'm known for my overpowering tactics.","Think you can take them?\nJust try to entertain me.","Let's go."],"after":["Strong Pokémon.","Weak Pokémon.","That is only the selfish perception\nof people.","Truly skilled Trainers should try to\nwin with the Pokémon they love best.","I like your style.\nYou understand what's important.","Go on--the Champion is waiting."],"look":{"sprite":"hgss_gsbigfour4","width":32,"height":32,"frames":9,"offsetX":-8}},{"trainer":"HGSS_TRAINER_CHAMPION_LANCE","rematch":"HGSS_TRAINER_CHAMPION_LANCE_2","intro":["Lance: I've been waiting for you.","{PLAYER}!","I knew that you, with your skills,\nwould eventually reach me here.","There's no need for words now.","We will battle to determine who is\nthe stronger of the two of us.","As the most powerful Trainer and as\nthe Pokémon League Champion...","I, Lance the dragon master,\naccept your challenge!"],"introGirl":["Lance: I've been waiting for you.","{PLAYER}!","I knew that you, with your skills,\nwould eventually reach me here.","There's no need for words now.","We will battle to determine who is\nthe stronger of the two of us.","As the most powerful Trainer and as\nthe Pokémon League Champion...","I, Lance the dragon master,\naccept your challenge!"],"after":["...Whew.","You have become truly powerful,\n{PLAYER}.","Your Pokémon have responded to your\nstrong and upstanding nature.","As a Trainer, you will continue to\ngrow strong with your Pokémon."],"afterGirl":["...Whew.","You have become truly powerful,\n{PLAYER}.","Your Pokémon have responded to your\nstrong and upstanding nature.","As a Trainer, you will continue to\ngrow strong with your Pokémon."],"look":{"sprite":"hgss_wataru","width":32,"height":32,"frames":9,"offsetX":-8}}];
